{"success": true, "data": {"stdout": "def solve_mckp_constrained(profiles, budget, mode="quant_only",
                           max_2bit=8, l0_exclude_2bit=True):
    """MCKP with cardinality constraints (D009).
    - max_2bit: at most K heads at 2-bit (K=8, manual experiment safe zone)
    - l0_exclude_2bit: Layer 0 heads excluded from 2-bit (cliff effect)
    """
    heads = []
    for l_str in sorted(profiles.keys(), key=lambda x: int(x)):
        for h_str in sorted(profiles[l_str].keys(), key=lambda x: int(x)):
            l, h = int(l_str), int(h_str)
            exclude = {2} if (l0_exclude_2bit and l == 0) else set()
            actions = _build_actions_no_pareto(profiles[l_str][h_str], mode, exclude)
            heads.append((l, h, actions))

    n_heads = len(heads)
    target = budget * n_heads
    current = {(l, h): 0 for l, h, _ in heads}
    total_memory = sum(a[0][0] for _, _, a in heads)
    n_2bit = 0

    while total_memory > target + 1e-9:
        best_eff = float("inf")
        best_saved = 0.0
        best_key = None
        best_idx = None

        for l, h, actions in heads:
            ci = current[(l, h)]
            if ci + 1 >= len(actions):
                continue
            curr = actions[ci]
            for ni in range(ci + 1, len(actions)):
                nxt = actions[ni]
                mem_saved = curr[0] - nxt[0]
                if mem_saved < 1e-12:
                    continue
                # D009: cardinality constraint on 2-bit
                is_2bit = (nxt[2] == "quant" and nxt[3] == 2)
                if is_2bit and max_2bit is not None and n_2bit >= max_2bit:
                    continue
                eff = (nxt[1] - curr[1]) / mem_saved
                # Prefer lower eff; break ties by larger mem_saved for faster convergence
                if eff < best_eff - 1e-12 or (abs(eff - best_eff) < 1e-12 and mem_saved > best_saved):
                    best_eff = eff
                    best_saved = mem_saved
                    best_key = (l, h)
                    best_idx = ni

        if best_key is None:
            break

        l, h = best_key
        for ll, hh, actions in heads:
            if ll == l and hh == h:
                old = actions[current[best_key]]
                new = actions[best_idx]
                total_memory -= (old[0] - new[0])
                was_2bit = (old[2] == "quant" and old[3] == 2)
                is_now_2bit = (new[2] == "quant" and new[3] == 2)
                if is_now_2bit and not was_2bit:
                    n_2bit += 1
                elif was_2bit and not is_now_2bit:
                    n_2bit -= 1
                current[best_key] = best_idx
                break

    allocation = {}
    total_dist = 0.0
    actual_mem = 0.0
    bit_dist = {}
    for l, h, actions in heads:
        a = actions[current[(l, h)]]
        allocation[f"{l},{h}"] = [a[2], a[3]]
        total_dist += a[1]
        actual_mem += a[0]
        b = a[3]
        bit_dist[b] = bit_dist.get(b, 0) + 1

    return {
        "allocation": allocation,
        "total_distortion": total_dist,
        "actual_memory_ratio": actual_mem / n_heads,
        "bit_distribution": bit_dist,
        "n_2bit": n_2bit,
    }


def solve_greedy_ratequant(profiles, budget=0.25, bit_options=None,
                           mode="quant_only"):
    """RateQuant-style greedy on discrete {2,4,8,16} bit-widths.
    Start all heads at max bit-width, greedily downgrade head with
    smallest marginal distortion/bit gain until budget met.
    """
    if bit_options is None:
        bit_options = [2, 4, 8, 16]
    bit_options = sorted(bit_options)

    heads = []
    for l_str in sorted(profiles.keys(), key=lambda x: int(x)):
        for h_str in sorted(profiles[l_str].keys(), key=lambda x: int(x)):
            l, h = int(l_str), int(h_str)
            qdata = profiles[l_str][h_str].get("quantization", {})
            distortion_map = {}
            for b in bit_options:
                if b == 16:
                    distortion_map[16] = 0.0
                else:
                    b_str = str(b)
                    if b_str in qdata:
                        distortion_map[b] = qdata[b_str]
                    elif str(float(b)) in qdata:
                        distortion_map[b] = qdata[str(float(b))]
            heads.append((l, h, distortion_map))

    n_heads = len(heads)
    allocation = [max(bit_options)] * n_heads
    target_mem = budget * n_heads * max(bit_options)

    def current_mem():
        return sum(allocation)

    while current_mem() > target_mem + 1e-9:
        best_head = None
        best_gain = float('inf')

        for i in range(n_heads):
            cur_bits = allocation[i]
            lower = [b for b in bit_options if b < cur_bits]
            if not lower:
                continue
            next_lower = max(lower)

            cur_dist = heads[i][2].get(cur_bits, 0.0)
            nxt_dist = heads[i][2].get(next_lower, None)
            if nxt_dist is None:
                continue

            bits_saved = cur_bits - next_lower
            dist_inc = nxt_dist - cur_dist
            marginal = dist_inc / bits_saved

            if marginal < best_gain:
                best_gain = marginal
                best_head = i

        if best_head is None:
            break

        cur = allocation[best_head]
        lower = [b for b in bit_options if b < cur]
        allocation[best_head] = max(lower)

    alloc_dict = {}
    total_dist = 0.0
    bit_dist = {}
    for i, (l, h, dmap) in enumerate(heads):
        b = allocation[i]
        alloc_dict[f"{l},{h}"] = ["quant" if b < 16 else "full", b]
        total_dist += dmap.get(b, 0.0)
        bit_dist[b] = bit_dist.get(b, 0) + 1

    actual_ratio = sum(allocation) / (n_heads * max(bit_options))

    return {
        "allocation": alloc_dict,
        "total_distortion": total_dist,
        "actual_memory_ratio": actual_ratio,
        "bit_distribution": bit_dist,
        "n_2bit": bit_dist.get(2, 0),
    }


def enforce_monotonicity(profiles):
    """Enforce delta(lower_bits) >= delta(higher_bits) via isotonic regression.
    Handles calibration noise where e.g. delta_4bit > delta_2bit.
    Returns a new profiles dict (original unchanged).
    """
    import copy
    enforced = copy.deepcopy(profiles)
    bit_order = [16, 8, 4, 2]  # high to low

    for l_str in enforced:
        for h_str in enforced[l_str]:
            qdata = enforced[l_str][h_str].get("quantization", {})
            if not qdata:
                continue
            # Collect deltas in descending bit order
            deltas = {}
            for b in bit_order:
                key = str(b)
                if key in qdata:
                    deltas[b] = qdata[key]
                elif b == 16:
                    deltas[16] = 0.0

            # Isotonic enforcement: scan from high to low bits
            # delta[b] = max(delta[b], delta[b_higher])
            prev = deltas.get(16, 0.0)
            for b in bit_order:
                if b not in deltas:
                    continue
                if deltas[b] < prev:
                    deltas[b] = prev
                prev = deltas[b]
                if b != 16:
                    qdata[str(b)] = deltas[b]

    return enforced
